tokens.css:
--color-bg: #fffcfd;
--color-surface: #faf3f6;
--color-text: #1f1a1c;
--color-text-muted: #6b5f63;
--color-border: #e6dde0;
--color-primary: #9a4a6b;
--color-on-primary: #ffffff;
--color-accent: #fffefe;
--color-on-accent: #ffffff;
--font-display: "Newsreader", Georgia, serif;
--font-body: "Instrument Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 4px;
--radius-card: 8px;
--space-section: 96px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
